import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz parameters: _baseToken and _nft are the deciding values; others are fuzzed but kept wide
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // keep feeRate within allowed bounds
        _feeRate = uint16(bound(_feeRate, 0, 5000));

        // Call initialize with fuzzed params and observe baseToken stored value afterwards.
        // We must call as some caller; use this contract as caller.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // if initialize reverts (e.g., AlreadyInitialized on repeated runs), treat as failure to initialize
            // but the property we assert only applies when initialize completed successfully.
            // To keep the domain admissible, require initialize succeeded.
            ok = false;
        }

        // If initialize didn't succeed, skip (do not assert) — but to follow rules we must make a single assertTrue reading c.
        // So only assert when initialize succeeded; otherwise trivially pass by returning early.
        if (!ok) return;

        // Single assertion: stored baseToken must equal the _baseToken argument
        // This holds for reference implementation for all inputs; mutant breaks when _nft == address(0)
        assertTrue(c.baseToken() == _baseToken);
