pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // General rule: after initialize(...) returns, the contract's public feeRate must equal the _feeRate argument passed in.
    // We expose this as a fuzz test: fuzz the parameters to initialize and assert c.feeRate() == _feeRate after the call.
    function testFuzz_property(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        // keep parameters wide but valid where needed
        // feeRate must be within uint16 (it already is) and initialize reverts if > 5000; we still fuzz across whole uint16 range

        // Call initialize and capture whether it succeeded or reverted. We don't constrain to avoid reverts because
        // initialize reverts only when already initialized (not the case) or when _feeRate > 5000; both are allowed inputs.
        bool ok;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: if initialize succeeded (did not revert), feeRate must equal the provided _feeRate parameter.
        // This is a universal property the reference satisfies for all inputs; the mutant that reorders assignments
        // breaks it for some inputs and so the fuzz will find a counterexample.
        if (ok) {
            assertTrue(c.feeRate() == _feeRate);
        } else {
            // If initialize reverted (e.g., _feeRate > 5000), we still must make a single assertTrue reading c's public surface.
            // In this case initialization didn't change state, so feeRate should remain its default (0) — which equals c.feeRate().
            // We assert that feeRate is either 0 (not-initialized) or equals _feeRate (in case revert happened after assignment in mutant).
            // To keep a single boolean, we assert that c.feeRate() == 0 || c.feeRate() == _feeRate.
            assertTrue(c.feeRate() == 0 || c.feeRate() == _feeRate);
        }
    }
}

